bool Del_Min(SqList &L, ElemType &value)
{
    if (L.length == 0) return false;        // 表空，报错退出
    value = L.data[0];                      // 先假定 0 号元素最小
    int pos = 0;
    for (int i = 1; i < L.length; i++)      // 遍历找最小值与其位置
        if (L.data[i] < value) { value = L.data[i]; pos = i; }
    L.data[pos] = L.data[L.length - 1];     // 最后一个元素填补空位
    L.length--;                             // 表长减一
    return true;
}

void Reverse(SqList &L)
{
    ElemType temp;
    for (int i = 0; i < L.length / 2; i++) {
        temp = L.data[i];
        L.data[i] = L.data[L.length - 1 - i];
        L.data[L.length - 1 - i] = temp;
    }
}

void del_x(SqList &L, ElemType x)
{
    int k = 0;                              // k 记录不等于 x 的元素个数
    for (int i = 0; i < L.length; i++)
        if (L.data[i] != x)
            L.data[k++] = L.data[i];        // 直接保留，覆盖前移
    L.length = k;                           // 新表长
}

bool del_s_t(SqList &L, ElemType s, ElemType t)
{
    if (L.length == 0 || s >= t) return false;   // 空表或 s、t 不合法
    int k = 0;
    for (int i = 0; i < L.length; i++) {
        if (L.data[i] >= s && L.data[i] <= t) k++;      // 落在区间：计数待删
        else L.data[i - k] = L.data[i];                 // 不在区间：前移 k 位
    }
    L.length -= k;
    return true;
}

bool del_s_t2(SqList &L, ElemType s, ElemType t)
{
    if (L.length == 0 || s >= t) return false;
    int i, j;
    for (i = 0; i < L.length && L.data[i] < s; i++);   // 找第一个 >=s 的元素
    if (i >= L.length) return false;                    // 所有元素都 < s，无可删
    for (j = i; j < L.length && L.data[j] <= t; j++);   // 找第一个 >t 的元素
    for (; j < L.length; i++, j++) L.data[i] = L.data[j]; // 整体前移覆盖
    L.length = i;
    return true;
}

bool Merge(SqList A, SqList B, SqList &C)
{
    if (A.length + B.length > C.MaxSize) return false;  // 容量不足
    int i = 0, j = 0, k = 0;
    while (i < A.length && j < B.length) {              // 两两比较，小者先入
        if (A.data[i] <= B.data[j]) C.data[k++] = A.data[i++];
        else C.data[k++] = B.data[j++];
    }
    while (i < A.length) C.data[k++] = A.data[i++];     // A 剩余
    while (j < B.length) C.data[k++] = B.data[j++];     // B 剩余
    C.length = k;
    return true;
}

void Reverse(ElemType A[], int left, int right)   // 逆置 A[left..right]
{
    while (left < right) {
        ElemType t = A[left];
        A[left] = A[right];
        A[right] = t;
        left++; right--;
    }
}
void Exchange(ElemType A[], int m, int n)         // A[m+n] 中前 m 个与后 n 个互换
{
    Reverse(A, 0, m + n - 1);   // 整体逆置
    Reverse(A, 0, n - 1);       // 前 n 个逆置
    Reverse(A, n, m + n - 1);   // 后 m 个逆置
}

int Partition(SqList &L, int low, int high)
{
    ElemType pivot = L.data[low];
    while (low < high) {
        while (low < high && L.data[high] >= pivot) high--;
        L.data[low] = L.data[high];
        while (low < high && L.data[low] <= pivot) low++;
        L.data[high] = L.data[low];
    }
    L.data[low] = pivot;        // 基准就位
    return low;                 // 返回基准最终位置
}
ElemType Kth(SqList &L, int low, int high, int k)
{
    if (low > high) return -1;              // 越界保护
    int m = Partition(L, low, high);        // 一趟划分
    if (m == k) return L.data[m];           // 恰为第 k 小
    if (m > k) return Kth(L, low, m - 1, k);
    else       return Kth(L, m + 1, high, k);
}
// 调用：Kth(L, 0, L.length-1, k-1)（k 从 1 计 → 下标 k-1）

void delX(LinkList &L, ElemType x)
{
    if (L == NULL) return;              // 递归终止
    if (L->data == x) {                 // 当前结点值等于 x
        LNode *p = L;
        L = L->next;                    // 改头指针（引用参数生效）
        free(p);
        delX(L, x);                     // 继续处理剩余
    } else {
        delX(L->next, x);               // 递归删除后续，结果接回
    }
}

void delX2(LinkList &L, ElemType x)
{
    LNode *pre = L, *p = L->next;       // pre 为 p 的前驱
    while (p != NULL) {
        if (p->data == x) {
            LNode *q = p;               // 暂存被删结点
            pre->next = p->next;        // 前驱跳过一个结点
            p = p->next;                // p 后移（pre 不动）
            free(q);
        } else {
            pre = p;                    // 同步后移
            p = p->next;
        }
    }
}

