ElemType delMin(LinkList L)
{
    if (L->next == NULL) return -1;          // 空表
    LNode *pre = L, *p = L->next;            // 工作指针
    LNode *minpre = L, *minp = L->next;      // 最小值及其前驱
    while (p != NULL) {
        if (p->data < minp->data) { minpre = pre; minp = p; }
        pre = p; p = p->next;
    }
    ElemType v = minp->data;
    minpre->next = minp->next;               // 摘下
    free(minp);
    return v;
}

void SortList(LinkList &L)
{
    LNode *p = L->next, *r;              // r 保存 p 的后继
    L->next = NULL;                      // 断开，L 变为空有序链
    while (p != NULL) {
        r = p->next;                     // 先存后继
        LNode *temp = L->next, *pre = L; // 在有序区找插入位置
        while (temp != NULL && temp->data < p->data) { pre = temp; temp = temp->next; }
        p->next = temp;                  // 前插到 pre 之后、temp 之前
        pre->next = p;
        p = r;                           // 处理原链下一个
    }
}

void delRange(LinkList &L, ElemType s, ElemType t)
{
    LNode *pre = L, *p = L->next;
    while (p != NULL) {
        if (p->data > s && p->data < t) {   // 值落在 (s,t) 内
            LNode *q = p;
            pre->next = p->next;
            p = p->next;
            free(q);
        } else { pre = p; p = p->next; }
    }
}

int Len(LinkList L) { int n = 0; L = L->next; while (L) { n++; L = L->next; } return n; }
LNode *findCommon(LinkList A, LinkList B)
{
    int na = Len(A), nb = Len(B), d = na > nb ? na - nb : nb - na;
    LNode *p = A->next, *q = B->next;
    if (na > nb) while (d--) p = p->next;
    else         while (d--) q = q->next;
    while (p != NULL && p != q) { p = p->next; q = q->next; }
    return p;                           // 公共结点或 NULL
}

