void split(LinkList A, LinkList &B)
{
    B = (LNode*)malloc(sizeof(LNode));  B->next = NULL;  // B 带头结点
    LNode *ra = A, *rb = B;             // 两表尾指针
    LNode *p = A->next;
    A->next = NULL;                     // 断开
    int odd = 1;                        // 从 1 号开始标记奇偶
    while (p != NULL) {
        LNode *r = p->next;
        if (odd) { ra->next = p; ra = p; }     // 奇数 → A
        else    { rb->next = p; rb = p; }     // 偶数 → B
        odd = !odd;
        p = r;
    }
    ra->next = NULL; rb->next = NULL;
}

void splitAB(LinkList hc, LinkList &A, LinkList &B)
{
    A = (LNode*)malloc(sizeof(LNode)); A->next = NULL;
    B = (LNode*)malloc(sizeof(LNode)); B->next = NULL;
    LNode *ra = A, *p = hc->next;          // ra 为 A 尾
    while (p != NULL) {
        LNode *r = p->next;                // 记录后继（可能是空）
        ra->next = p; ra = p;              // a 尾插进 A
        p = r;
        if (p != NULL) {                   // 还有 b
            r = p->next;
            p->next = B->next; B->next = p;// b 头插进 B（得逆序）
            p = r;
        }
    }
    ra->next = NULL;                       // 封尾
}

void dedup(LinkList &L)
{
    LNode *p = L->next;
    while (p != NULL && p->next != NULL) {
        if (p->data == p->next->data) {     // 相邻相同 → 删后一个
            LNode *q = p->next;
            p->next = q->next;
            free(q);
        } else p = p->next;
    }
}

LinkList mergeDesc(LinkList A, LinkList B)
{
    LNode *p = A->next, *q = B->next;
    A->next = NULL;                       // A 头结点作结果链头
    while (p != NULL && q != NULL) {
        if (p->data <= q->data) {         // 取较小的 p
            LNode *r = p->next;
            p->next = A->next; A->next = p;   // 头插
            p = r;
        } else {
            LNode *r = q->next;
            q->next = A->next; A->next = q;   // 头插
            q = r;
        }
    }
    while (p) { LNode *r = p->next; p->next = A->next; A->next = p; p = r; }
    while (q) { LNode *r = q->next; q->next = A->next; A->next = q; q = r; }
    return A;
}

LinkList getCommon(LinkList A, LinkList B)
{
    LinkList C = (LNode*)malloc(sizeof(LNode));
    C->next = NULL;
    LNode *p = A->next, *q = B->next, *rc = C;
    while (p != NULL && q != NULL) {
        if (p->data < q->data) p = p->next;
        else if (p->data > q->data) q = q->next;
        else {                            // 相等：复制进 C
            LNode *s = (LNode*)malloc(sizeof(LNode));
            s->data = p->data;
            rc->next = s; rc = s;
            p = p->next; q = q->next;
        }
    }
    rc->next = NULL;
    return C;
}

int isSubSeq(LinkList A, LinkList B)
{
    LNode *pre = A->next, *pa = A->next, *pb = B->next;
    while (pa && pb) {
        if (pa->data == pb->data) { pa = pa->next; pb = pb->next; }
        else {                       // 失配：A 回溯到下一位
            pre = pre->next; pa = pre; pb = B->next;
        }
    }
    return pb == NULL;               // B 走完 = 匹配成功
}

typedef struct BTNode {
    int data;
    struct BTNode *left, *right;
} BTNode;
int treeHeight(BTNode *p)
{
    if (p == NULL) return 0;
    int lh = treeHeight(p->left);
    int rh = treeHeight(p->right);
    return (lh > rh ? lh : rh) + 1;
}

typedef struct BTNode {
    int data;
    struct BTNode *left, *right;
} BTNode;
int leafCount(BTNode *p)
{
    if (p == NULL) return 0;
    if (p->left == NULL && p->right == NULL) return 1;   // 叶子
    return leafCount(p->left) + leafCount(p->right);
}

typedef struct BTNode {
    int data;
    struct BTNode *left, *right;
} BTNode;
// Q 为队列（顺序存储，front/rear 下标），EnQ / DeQ 为入队出队
int isComplete(BTNode *root)
{
    if (root == NULL) return 1;
    BTNode *Q[1000]; int front = 0, rear = 0;
    BTNode *p;
    Q[rear++] = root;
    int flag = 0;                       // 0 未遇空，1 已遇空
    while (front < rear) {
        p = Q[front++];
        if (p == NULL) { flag = 1; continue; }   // 遇空标记
        if (flag) return 0;             // 空后还有非空 → 非完全
        Q[rear++] = p->left;            // 空孩子也入队
        Q[rear++] = p->right;
    }
    return 1;
}

typedef struct BTNode {
    int data;
    struct BTNode *left, *right;
} BTNode;
int doubleCount(BTNode *p)
{
    if (p == NULL) return 0;
    int c = (p->left && p->right) ? 1 : 0;   // 双分支结点
    return c + doubleCount(p->left) + doubleCount(p->right);
}

typedef struct BTNode {
    int data;
    struct BTNode *left, *right;
} BTNode;
BTNode* build(int A[], int B[], int preL, int preR, int inL, int inR)
{
    if (preL > preR) return NULL;
    BTNode *r = (BTNode*)malloc(sizeof(BTNode));
    r->data = A[preL];                  // 先序首元素为根
    int k = inL;
    while (B[k] != A[preL]) k++;        // 中序中定位根
    int lsize = k - inL;                // 左子树结点数
    r->left  = build(A, B, preL + 1,   preL + lsize, inL,   k - 1);
    r->right = build(A, B, preL + lsize + 1, preR, k + 1, inR);
    return r;
}

typedef struct BTNode {
    int data;
    struct BTNode *left, *right;
} BTNode;
void swapLR(BTNode *p)
{
    if (p == NULL) return;
    swapLR(p->left);                    // 左子树内部互换
    swapLR(p->right);                   // 右子树内部互换
    BTNode *t = p->left;                // 当前结点左右互换
    p->left = p->right;
    p->right = t;
}

typedef struct BTNode {
    int data;
    struct BTNode *left, *right;
} BTNode;
int count = 0, found = 0, ans = -1;
void preKth(BTNode *p, int k)
{
    if (p == NULL || found) return;     // 已找到则停止
    if (++count == k) { ans = p->data; found = 1; return; }
    preKth(p->left, k);
    preKth(p->right, k);
}

typedef struct BTNode {
    int data;
    struct BTNode *left, *right;
} BTNode;
// 栈项类型：结点 + 访问标志（0 首次，1 表示左子树已处理完）
void printAncestors(BTNode *root, int x)
{
    BTNode *S[1000]; int tag[1000], top = -1;
    BTNode *p = root;
    while (p != NULL || top != -1) {
        while (p != NULL) { S[++top] = p; tag[top] = 0; p = p->left; }
        if (tag[top] == 0) { tag[top] = 1; p = S[top]->right; }
        else {
            BTNode *v = S[top--];
            if (v->data == x) {          // 栈中剩余即为祖先
                while (top >= 0) printf("%d ", S[top--]->data);
                return;
            }
        }
    }
}

typedef struct BTNode {
    int data;
    struct BTNode *left, *right;
} BTNode;
int treeWidth(BTNode *root)
{
    BTNode *Q[1000]; int front = 0, rear = 0;
    Q[rear++] = root;
    BTNode *last = root, *newlast = root;   // 层尾标记
    int cur = 0, maxW = 0;
    while (front < rear) {
        BTNode *p = Q[front++];
        cur++;
        if (p->left)  { Q[rear++] = p->left;  newlast = p->left; }
        if (p->right) { Q[rear++] = p->right; newlast = p->right; }
        if (p == last) {                     // 本层结束
            if (cur > maxW) maxW = cur;
            cur = 0;
            last = newlast;
        }
    }
    return maxW;
}
